    const line = ov.length ? `${plural(ov.length, "clinical day")} went over ${lim} (highest ${hi.ratio}, ${hi.group || hi.date}).` : tr.length ? `${plural(tr.length, "scheduled clinical day")} would go over ${lim} (highest ${hi.ratio}${hi.group ? ", " + hi.group : ""}).` : `All ${rows.length} ${set === "inpatient" ? "inpatient " : ""}clinical days are within ${lim} (highest ${hi.ratio}).`;
