    const lim = s => { const m = v.max_students_per_preceptor; if (typeof m === "number") return m; if (m && typeof m === "object") return s.setting === "ltc" ? m.nursing_home : m.hospital_office_clinic; return null };
    const rows = ss.map(s => { const n = (s.students || []).filter(x => !(x.status === "absent" || x.status === "excused")).length; const l = lim(s); return { id: s.id, date: s.date, group: s.group_name || "", setting: s.setting || "", students: n, limit: l, state: l != null && n > l ? (s.date <= data.today ? "over" : "trend") : "ok" } });
    const ov = rows.filter(r => r.state === "over"), tr = rows.filter(r => r.state === "trend");
    const status = ov.length ? "notmet" : tr.length ? "risk" : "met";
