const GUIDANCE = {"schema":"vexcura.regs.guidance/1","version":"2026-11-06.1","id":"NCSBN","kind":"guidance","title":"NCSBN national guidance (not binding)","verified":"2026-11-06","items":[{"title":"NCSBN Simulation Guidelines for Prelicensure Nursing Programs","text":"High-quality simulation may substitute for up to 50% of traditional clinical hours when program conditions are met (trained faculty, INACSL standards, theory-based debriefing, dedicated lab). Boards should collect simulation data in annual reports. Still the current version (2015; file labeled 2016) as of 2026-11-06.","cite":{"text":"Alexander et al., J Nurs Regul 2015, 6(3); Hayden et al., J Nurs Regul 2014, 5(2 Suppl)","url":"https://www.ncsbn.org/research-item/ncsbn-simulation-guidelines-for-prelicensure-nursing-programs","effective":"2015","verified":"2026-11-06","binding":"guidance","confidence":"high"}},{"title":"NCSBN Model Rules, chapter 6 (revised August 2026)","text":"Simulation counts 1:1; at most 50% per specialty if the program has 600 or more direct-care hours, otherwise 25%; screen-based simulation does not count for direct care; at least 50% direct care per content area. Model rules bind no one until a state adopts them.","cite":{"text":"NCSBN Model Rules (2026) ch. 6: 6.1.1.A.4-6, 6.1.1.D.3","url":"https://ncsbn.org/public-files/2026_ncsbn_model_rules.pdf","effective":"Revised August 2026","verified":"2026-11-05","binding":"guidance","confidence":"medium"}}]};
